insert into public.illness_scripts (id, version, status, reviewed_by, reviewed_at, content) values
  ('zorblax-syndrome', 1, 'approved', 'TEST', '2026-11-13T00:00:00Z', '{"name":"Zorblax syndrome","aliases":["ZBX"],"rotation":["IM"],"epidemiology":{"who":"Fictional adults over 40 (test fixture, not a real disease)","risk_factors":["glimmer exposure","night shift work","low blorp diet","family history"]},"pathophysiology":"Fictional autoimmune attack on the glimmer gland.","timeline":{"onset":"Subacute, over weeks","course":"Relapsing-remitting"},"key_findings":{"history":["purple fatigue","itchy elbows"],"exam":["blue nail beds"],"labs":["high serum blorp"],"imaging":["swollen glimmer gland on ultrasound"]},"diagnosis":{"confirmatory_tests":["anti-glimmer antibody"],"criteria":["serum blorp above 40 units with blue nail beds"]},"management":{"first_line":["zorbicillin"],"next_line":["plasma swap"]},"complications":["glimmer storm"],"confused_with":[{"script_id":"quellan-fever","how_to_tell_apart":"Quellan fever causes green nail beds and a normal blorp."}],"pearls":["Zorblax syndrome never causes fever."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["key_findings.exam[0]","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[{"kind":"note","id":"1000000001"}],"sources":[{"title":"Rounds test fixture (fictional)"}]}'::jsonb),
  ('quellan-fever', 1, 'approved', 'TEST', '2026-11-13T00:00:00Z', '{"name":"Quellan fever","aliases":["QF"],"rotation":["IM"],"epidemiology":{"who":"Fictional travelers (test fixture)","risk_factors":["quellan bites"]},"pathophysiology":"Fictional infection of the nail matrix.","timeline":{"onset":"Acute, over days","course":"Self-limited"},"key_findings":{"history":["fever","purple fatigue"],"exam":["green nail beds"],"labs":["normal blorp"],"imaging":[]},"diagnosis":{"confirmatory_tests":["quellan PCR"],"criteria":[]},"management":{"first_line":["supportive care"],"next_line":[]},"complications":[],"confused_with":[{"script_id":"zorblax-syndrome","how_to_tell_apart":"Zorblax syndrome causes blue nail beds, high blorp and no fever."}],"pearls":[],"difficulty_tiers":{"MS1-2":[],"MS3":["key_findings.exam[0]"],"MS4":[]},"anki_refs":[],"sources":[{"title":"Rounds test fixture (fictional)"}]}'::jsonb),
  ('acute-pancreatitis', 1, 'in_review', null, null, '{"name":"Acute pancreatitis","aliases":[],"rotation":["IM","surgery"],"epidemiology":{"who":"Adults; gallstones are the most common cause, then heavy alcohol use","risk_factors":["gallstones","alcohol","hypertriglyceridemia","post-ERCP","medications","hypercalcemia"]},"pathophysiology":"Premature activation of pancreatic enzymes (trypsin) inside the gland causes autodigestion and local inflammation, which can become a systemic inflammatory response.","timeline":{"onset":"Sudden, over hours","course":"Mild disease settles within a week; severe disease brings organ failure lasting over 48 hours and local complications"},"key_findings":{"history":["sudden epigastric pain radiating to the back","nausea and vomiting","recent heavy alcohol use or known gallstones"],"exam":["epigastric tenderness","tachycardia","flank or periumbilical bruising in severe disease"],"labs":["lipase more than 3 times the upper limit of normal","raised ALT in gallstone pancreatitis"],"imaging":["right upper quadrant ultrasound to look for gallstones","contrast CT only if the diagnosis is unclear or the patient is not improving"]},"diagnosis":{"confirmatory_tests":["serum lipase","right upper quadrant ultrasound"],"criteria":["two of three: typical epigastric pain, lipase more than 3 times the upper limit of normal, characteristic imaging findings"]},"management":{"first_line":["early goal-directed IV fluids with lactated Ringer''s","pain control","early oral feeding as tolerated"],"next_line":["cholecystectomy during the same admission for mild gallstone pancreatitis","ERCP within 24 hours if there is cholangitis","no prophylactic antibiotics"]},"complications":["pancreatic pseudocyst","walled-off necrosis","infected necrosis","ARDS","acute kidney injury"],"confused_with":[{"script_id":"diabetic-ketoacidosis","how_to_tell_apart":"DKA can cause abdominal pain and a mildly raised lipase, but it has high glucose, ketones and an anion gap acidosis, and the pain improves as the acidosis is treated."}],"pearls":["Gallstone pancreatitis is suggested by an ALT more than 3 times the upper limit of normal."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["key_findings.history[0]","diagnosis.criteria[0]","management.first_line"],"MS4":["pearls[0]","management.next_line[0]"]},"anki_refs":[],"sources":[{"title":"American College of Gastroenterology Guideline: Management of Acute Pancreatitis (2024)"},{"title":"Classification of acute pancreatitis: revision of the Atlanta classification by international consensus (2012)"}]}'::jsonb),
  ('atrial-fibrillation', 1, 'in_review', null, null, '{"name":"Atrial fibrillation","aliases":["AF","AFib"],"rotation":["IM","EM","FM"],"epidemiology":{"who":"Mostly older adults; prevalence rises sharply with age","risk_factors":["older age","hypertension","heart failure","valvular heart disease","obesity","obstructive sleep apnea","alcohol","hyperthyroidism"]},"pathophysiology":"Disorganized atrial electrical activity, often triggered from the pulmonary veins, causes loss of atrial contraction and an irregular ventricular response; stasis in the left atrial appendage lets clot form and embolize.","timeline":{"onset":"Sudden or unnoticed","course":"Often starts paroxysmal and becomes persistent or permanent over time"},"key_findings":{"history":["palpitations","dyspnea","fatigue","lightheadedness","sometimes no symptoms"],"exam":["irregularly irregular pulse","variable intensity of S1"],"labs":["TSH to look for hyperthyroidism"],"imaging":["echocardiogram for chamber size, valves and ejection fraction"]},"diagnosis":{"confirmatory_tests":["12-lead ECG"],"criteria":["ECG: irregularly irregular rhythm with no discernible P waves"]},"management":{"first_line":["rate control with a beta-blocker or a nondihydropyridine calcium channel blocker","anticoagulation based on stroke risk (CHA2DS2-VASc)","synchronized cardioversion if hemodynamically unstable"],"next_line":["rhythm control with cardioversion, antiarrhythmic drugs or catheter ablation","if AF has lasted 48 hours or more or the duration is unknown, anticoagulate for 3 weeks before elective cardioversion or exclude clot with a transesophageal echocardiogram"]},"complications":["ischemic stroke","systemic embolism","tachycardia-induced cardiomyopathy","heart failure"],"confused_with":[],"pearls":["Direct oral anticoagulants are preferred over warfarin, except with a mechanical heart valve or moderate to severe mitral stenosis."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.criteria[0]","management.first_line"],"MS4":["pearls[0]","management.next_line[1]"]},"anki_refs":[],"sources":[{"title":"2023 ACC/AHA/ACCP/HRS Guideline for the Diagnosis and Management of Atrial Fibrillation"}]}'::jsonb),
  ('community-acquired-pneumonia', 1, 'in_review', null, null, '{"name":"Community-acquired pneumonia","aliases":["CAP"],"rotation":["IM","EM","FM"],"epidemiology":{"who":"Adults living in the community; risk rises with age and chronic lung disease","risk_factors":["age 65 or older","smoking","COPD","alcohol use disorder","immunosuppression"]},"pathophysiology":"Infection of the lung parenchyma, usually after aspiration of upper airway organisms. Streptococcus pneumoniae is the most common cause; others include Haemophilus influenzae, Mycoplasma pneumoniae, respiratory viruses, Staphylococcus aureus and Legionella.","timeline":{"onset":"Acute, over a few days","course":"Most patients improve within 48 to 72 hours of appropriate antibiotics"},"key_findings":{"history":["fever","cough with sputum","pleuritic chest pain","dyspnea"],"exam":["focal crackles","bronchial breath sounds","dullness to percussion","tachypnea"],"labs":["leukocytosis","hypoxemia"],"imaging":["chest X-ray showing a new lobar or focal infiltrate"]},"diagnosis":{"confirmatory_tests":["chest X-ray"],"criteria":["compatible symptoms plus a new infiltrate on chest imaging"]},"management":{"first_line":["outpatient without comorbidities: amoxicillin or doxycycline (a macrolide only where pneumococcal macrolide resistance is below 25%)","outpatient with comorbidities: amoxicillin-clavulanate or a cephalosporin plus a macrolide or doxycycline, or a respiratory fluoroquinolone alone","inpatient, not severe: ceftriaxone plus azithromycin, or a respiratory fluoroquinolone alone"],"next_line":["add MRSA or Pseudomonas coverage only with prior isolation of those organisms or other validated risk factors","ICU admission for severe pneumonia"]},"complications":["parapneumonic effusion","empyema","sepsis","ARDS","lung abscess"],"confused_with":[{"script_id":"pulmonary-embolism","how_to_tell_apart":"Pulmonary embolism also causes pleuritic pain, dyspnea and tachycardia, but usually has clear lungs and a near-normal chest X-ray despite hypoxemia; suspect it when there are risk factors for clots."},{"script_id":"heart-failure-exacerbation","how_to_tell_apart":"Heart failure gives bilateral crackles, a raised JVP, leg edema and a high BNP, with bilateral interstitial edema and effusions on X-ray rather than a focal consolidation, and usually no fever."}],"pearls":["CURB-65 (confusion, urea over 19 mg/dL, respiratory rate 30 or more, low blood pressure, age 65 or older) is a quick bedside guide to admission; the ATS/IDSA guideline prefers the Pneumonia Severity Index."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["key_findings.exam","diagnosis.confirmatory_tests","management.first_line[0]"],"MS4":["pearls[0]","management.next_line[0]"]},"anki_refs":[],"sources":[{"title":"Diagnosis and Treatment of Adults with Community-acquired Pneumonia: An Official Clinical Practice Guideline of the ATS and IDSA (2019)"}]}'::jsonb),
  ('diabetic-ketoacidosis', 1, 'in_review', null, null, '{"name":"Diabetic ketoacidosis","aliases":["DKA"],"rotation":["IM","EM"],"epidemiology":{"who":"Mostly people with type 1 diabetes, often as the first presentation; also type 2 diabetes under acute stress or on SGLT2 inhibitors","risk_factors":["infection","insulin omission","new-onset diabetes","SGLT2 inhibitors","myocardial infarction","pancreatitis"]},"pathophysiology":"Insulin deficiency plus excess counterregulatory hormones (glucagon, cortisol, catecholamines) drive lipolysis and hepatic ketogenesis, causing an anion gap metabolic acidosis. Hyperglycemia causes an osmotic diuresis with volume depletion and a total-body potassium deficit.","timeline":{"onset":"Develops over hours, usually less than 24 hours","course":"Resolves over about a day with fluids, insulin and potassium; can recur if the precipitant is not treated"},"key_findings":{"history":["polyuria and polydipsia","nausea and vomiting","abdominal pain"],"exam":["Kussmaul respirations (deep, rapid breathing)","fruity (acetone) breath","signs of volume depletion: tachycardia, dry mucous membranes"],"labs":["glucose usually above 250 mg/dL","anion gap metabolic acidosis","raised serum beta-hydroxybutyrate","serum potassium often normal or high despite a total-body deficit"],"imaging":[]},"diagnosis":{"confirmatory_tests":["serum beta-hydroxybutyrate","venous blood gas","basic metabolic panel with anion gap"],"criteria":["glucose of 200 mg/dL or more, or known diabetes","ketosis: beta-hydroxybutyrate of 3.0 mmol/L or more, or urine ketones 2+ or more","acidosis: pH below 7.3 and/or bicarbonate below 18 mEq/L"]},"management":{"first_line":["IV isotonic fluids","IV insulin infusion","potassium replacement"],"next_line":["add dextrose to the fluids when glucose falls below 250 mg/dL","bicarbonate only if pH is below 7.0","overlap subcutaneous basal insulin by 1 to 2 hours before stopping the infusion","treat the precipitant"]},"complications":["hypokalemia","hypoglycemia","cerebral edema, mainly in children","recurrence after stopping the infusion too early"],"confused_with":[{"script_id":"acute-pancreatitis","how_to_tell_apart":"DKA causes abdominal pain and can raise lipase, but the labs show an anion gap acidosis with high ketones, and the pain eases as the acidosis is corrected; in pancreatitis the pain persists and imaging shows an inflamed pancreas."}],"pearls":["Check potassium before starting insulin: if it is below 3.5 mEq/L, replace it first and hold insulin, because insulin drives potassium into cells."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["key_findings.exam[0]","management.first_line","diagnosis.criteria"],"MS4":["pearls[0]","management.next_line"]},"anki_refs":[],"sources":[{"title":"Hyperglycemic Crises in Adults With Diabetes: A Consensus Report (Diabetes Care, 2024)"}]}'::jsonb),
  ('heart-failure-exacerbation', 1, 'in_review', null, null, '{"name":"Acute decompensated heart failure","aliases":["heart failure exacerbation","ADHF","CHF exacerbation"],"rotation":["IM","EM"],"epidemiology":{"who":"Adults with known chronic heart failure, with reduced or preserved ejection fraction","risk_factors":["high salt intake","medication nonadherence","myocardial ischemia","atrial fibrillation","uncontrolled hypertension","infection","NSAIDs"]},"pathophysiology":"Worsening cardiac function or a precipitant raises left-sided filling pressures, causing pulmonary congestion, while sodium and water retention cause systemic venous congestion.","timeline":{"onset":"Usually over days, sometimes hours","course":"Most improve with diuresis over several days; each admission marks a worse long-term prognosis"},"key_findings":{"history":["worsening dyspnea","orthopnea","paroxysmal nocturnal dyspnea","weight gain","leg swelling"],"exam":["raised JVP","bibasilar crackles","S3 gallop","pitting edema"],"labs":["raised BNP or NT-proBNP","troponin may be mildly raised"],"imaging":["chest X-ray: pulmonary vascular congestion, interstitial edema, Kerley B lines, pleural effusions","echocardiogram to assess ejection fraction"]},"diagnosis":{"confirmatory_tests":["BNP or NT-proBNP","echocardiogram","chest X-ray"],"criteria":["clinical diagnosis: symptoms and signs of congestion, supported by a raised natriuretic peptide"]},"management":{"first_line":["IV loop diuretics such as furosemide","supplemental oxygen if hypoxemic","treat the precipitant"],"next_line":["add a thiazide-type diuretic such as metolazone if diuresis is inadequate","noninvasive ventilation for respiratory distress","vasodilators such as nitroglycerin if hypertensive","inotropes for low output with hypoperfusion"]},"complications":["cardiogenic shock","acute kidney injury","arrhythmias","hypokalemia from diuresis"],"confused_with":[{"script_id":"community-acquired-pneumonia","how_to_tell_apart":"Pneumonia usually brings fever, productive cough and a focal consolidation; heart failure gives bilateral crackles, a raised JVP, leg edema and a high BNP."}],"pearls":["The first IV loop diuretic dose should equal or exceed the patient''s total daily oral dose."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["key_findings.exam","diagnosis.confirmatory_tests","management.first_line[0]"],"MS4":["pearls[0]","management.next_line[0]"]},"anki_refs":[],"sources":[{"title":"2022 AHA/ACC/HFSA Guideline for the Management of Heart Failure"}]}'::jsonb),
  ('nephritic-syndrome', 1, 'in_review', null, null, '{"name":"Nephritic syndrome","aliases":["acute glomerulonephritis"],"rotation":["IM","peds"],"epidemiology":{"who":"Children and adults; post-infectious glomerulonephritis is common in children, and IgA nephropathy is the most common glomerulonephritis worldwide","risk_factors":["post-streptococcal glomerulonephritis","IgA nephropathy","lupus nephritis","ANCA-associated vasculitis","anti-GBM disease","infective endocarditis"]},"pathophysiology":"Immune-mediated inflammation of the glomeruli damages the capillary walls, letting red cells into the urine and lowering filtration, which causes salt and water retention, hypertension and a rising creatinine.","timeline":{"onset":"Days to weeks","course":"Post-streptococcal disease usually resolves in children; rapidly progressive forms can cause kidney failure within weeks"},"key_findings":{"history":["cola-colored urine","reduced urine output","recent sore throat or skin infection"],"exam":["hypertension","periorbital or leg edema"],"labs":["hematuria with red blood cell casts and dysmorphic red cells","rising creatinine","proteinuria usually below 3.5 g/day","low complement C3 in post-streptococcal glomerulonephritis and lupus nephritis"],"imaging":[]},"diagnosis":{"confirmatory_tests":["urinalysis with microscopy for red blood cell casts","complement levels (C3 and C4)","serologies: ANCA, anti-GBM, ANA, ASO","kidney biopsy"],"criteria":["hematuria with red cell casts, hypertension, edema and reduced kidney function"]},"management":{"first_line":["supportive care","blood pressure control","loop diuretics and salt restriction for fluid overload","treat the underlying cause"],"next_line":["immunosuppression (steroids with cyclophosphamide or rituximab) for rapidly progressive disease such as ANCA vasculitis","plasma exchange for anti-GBM disease","dialysis for refractory fluid overload, hyperkalemia or uremia"]},"complications":["acute kidney injury","hypertensive emergency","pulmonary edema","progression to chronic kidney disease"],"confused_with":[{"script_id":"nephrotic-syndrome","how_to_tell_apart":"Nephrotic syndrome has heavy proteinuria above 3.5 g/day, low albumin and a bland urine sediment; nephritic syndrome has red blood cell casts, hypertension and a rising creatinine."}],"pearls":["IgA nephropathy causes hematuria within a few days of an upper respiratory infection, while post-streptococcal glomerulonephritis appears 1 to 3 weeks after a sore throat."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["key_findings.labs[0]","epidemiology.risk_factors","management.first_line"],"MS4":["pearls[0]","management.next_line[1]"]},"anki_refs":[],"sources":[{"title":"KDIGO 2021 Clinical Practice Guideline for the Management of Glomerular Diseases"}]}'::jsonb),
  ('nephrotic-syndrome', 1, 'in_review', null, null, '{"name":"Nephrotic syndrome","aliases":[],"rotation":["IM","peds"],"epidemiology":{"who":"Children, usually from minimal change disease, and adults, most often from membranous nephropathy, FSGS or diabetic kidney disease","risk_factors":["minimal change disease","focal segmental glomerulosclerosis","membranous nephropathy","diabetic nephropathy","amyloidosis","lupus nephritis"]},"pathophysiology":"Injury to the glomerular filtration barrier (the podocytes) lets large amounts of protein leak into the urine, causing low serum albumin, edema and a compensatory rise in hepatic lipoprotein synthesis. Urinary loss of anticoagulant proteins makes patients hypercoagulable.","timeline":{"onset":"Usually over weeks","course":"Minimal change disease often remits with steroids; other causes may progress to chronic kidney disease"},"key_findings":{"history":["swelling around the eyes and legs","foamy urine","weight gain"],"exam":["pitting edema","periorbital edema","ascites or pleural effusions"],"labs":["proteinuria above 3.5 g/day","serum albumin below 3 g/dL","hyperlipidemia","fatty casts and oval fat bodies in the urine"],"imaging":[]},"diagnosis":{"confirmatory_tests":["urine protein-to-creatinine ratio","24-hour urine protein","kidney biopsy to find the cause in adults"],"criteria":["proteinuria above 3.5 g/day with hypoalbuminemia and edema; hyperlipidemia is common"]},"management":{"first_line":["ACE inhibitor or ARB to reduce proteinuria","loop diuretics and salt restriction for edema","treat the underlying cause"],"next_line":["corticosteroids for minimal change disease","statin for persistent hyperlipidemia","anticoagulation for thrombosis"]},"complications":["renal vein thrombosis","deep vein thrombosis and pulmonary embolism","infection","acute kidney injury"],"confused_with":[{"script_id":"nephritic-syndrome","how_to_tell_apart":"Nephritic syndrome has hematuria with red blood cell casts, hypertension and a rising creatinine, with proteinuria usually below 3.5 g/day; nephrotic syndrome has heavy proteinuria above 3.5 g/day with a bland sediment."}],"pearls":["Urinary loss of antithrombin III makes nephrotic patients hypercoagulable; renal vein thrombosis is classic with membranous nephropathy."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.criteria[0]","epidemiology.risk_factors","management.first_line[0]"],"MS4":["pearls[0]"]},"anki_refs":[],"sources":[{"title":"KDIGO 2021 Clinical Practice Guideline for the Management of Glomerular Diseases"}]}'::jsonb),
  ('pulmonary-embolism', 1, 'in_review', null, null, '{"name":"Pulmonary embolism","aliases":["PE"],"rotation":["IM","EM","surgery"],"epidemiology":{"who":"Adults with risk factors for venous thromboembolism","risk_factors":["recent surgery","immobilization","active cancer","prior VTE","estrogen use or pregnancy","inherited thrombophilia"]},"pathophysiology":"A thrombus, usually from the deep veins of the legs, lodges in the pulmonary arteries, causing ventilation-perfusion mismatch and hypoxemia; a large clot strains the right ventricle and can cause shock.","timeline":{"onset":"Sudden","course":"Most stable patients recover with anticoagulation; massive PE can cause sudden death"},"key_findings":{"history":["sudden dyspnea","pleuritic chest pain","hemoptysis","unilateral leg swelling"],"exam":["tachycardia","tachypnea","hypoxemia","clear lungs"],"labs":["raised D-dimer","raised troponin or BNP with right ventricular strain"],"imaging":["CT pulmonary angiography showing a filling defect","echocardiogram may show right ventricular dilation"]},"diagnosis":{"confirmatory_tests":["CT pulmonary angiography","V/Q scan if CT contrast is contraindicated"],"criteria":["use the Wells score to estimate pretest probability","with low pretest probability, a negative D-dimer rules out PE"]},"management":{"first_line":["anticoagulation, preferably a direct oral anticoagulant such as apixaban or rivaroxaban"],"next_line":["systemic thrombolysis for high-risk PE with hypotension","catheter-directed therapy or surgical embolectomy if thrombolysis fails or is contraindicated","IVC filter only if anticoagulation is contraindicated"]},"complications":["right heart failure","obstructive shock","pulmonary infarction","chronic thromboembolic pulmonary hypertension"],"confused_with":[{"script_id":"community-acquired-pneumonia","how_to_tell_apart":"Pneumonia usually brings fever, productive cough, focal crackles and a consolidation on chest X-ray; PE more often has clear lungs and a near-normal X-ray despite hypoxemia."}],"pearls":["The most common ECG finding in PE is sinus tachycardia; the classic S1Q3T3 pattern is uncommon."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["epidemiology.risk_factors","diagnosis.confirmatory_tests[0]","management.first_line[0]"],"MS4":["pearls[0]","management.next_line[0]","diagnosis.criteria[1]"]},"anki_refs":[],"sources":[{"title":"2019 ESC Guidelines for the diagnosis and management of acute pulmonary embolism"},{"title":"Antithrombotic Therapy for VTE Disease: Second Update of the CHEST Guideline and Expert Panel Report (2021)"}]}'::jsonb);
insert into public.questions (id, script_id, script_version, rung, content) values
  ('zorblax-syndrome.recall.1', 'zorblax-syndrome', 1, 'recall', '{"prompt":"An adult has purple fatigue, itchy elbows and blue nail beds. Most likely diagnosis?","source_fields":["name"],"accepted_answers":[{"answer":"Zorblax syndrome","synonyms":["zorblax","ZBX"]}],"kind":"single"}'::jsonb),
  ('zorblax-syndrome.second-order.1', 'zorblax-syndrome', 1, 'second_order', '{"prompt":"Name 3 risk factors for Zorblax syndrome.","source_fields":["epidemiology.risk_factors"],"accepted_answers":[{"answer":"glimmer exposure","synonyms":["glimmer"]},{"answer":"night shift work","synonyms":["night shift","shift work"]},{"answer":"low blorp diet","synonyms":["low blorp"]},{"answer":"family history","synonyms":["family hx","genetics"]}],"kind":"list","required_count":3}'::jsonb),
  ('zorblax-syndrome.differentiate.1', 'zorblax-syndrome', 1, 'differentiate', '{"prompt":"On exam, how do you tell it apart from Quellan fever?","source_fields":["key_findings.exam","confused_with[0].how_to_tell_apart"],"accepted_answers":[{"answer":"blue nail beds","synonyms":["blue nails"]},{"answer":"green nail beds","synonyms":["green nails"]}],"kind":"single"}'::jsonb),
  ('zorblax-syndrome.workup.1', 'zorblax-syndrome', 1, 'workup', '{"prompt":"What test confirms the diagnosis?","source_fields":["diagnosis.confirmatory_tests"],"accepted_answers":[{"answer":"anti-glimmer antibody","synonyms":["anti glimmer","glimmer antibody"]}],"kind":"single"}'::jsonb),
  ('zorblax-syndrome.management.1', 'zorblax-syndrome', 1, 'management', '{"prompt":"First-line treatment?","source_fields":["management.first_line"],"accepted_answers":[{"answer":"zorbicillin","synonyms":[]}],"kind":"single"}'::jsonb),
  ('zorblax-syndrome.pearl.1', 'zorblax-syndrome', 1, 'pearl', '{"prompt":"Which vital-sign finding argues against Zorblax syndrome?","source_fields":["pearls[0]"],"accepted_answers":[{"answer":"fever","synonyms":["febrile","high temperature"]}],"kind":"single"}'::jsonb),
  ('acute-pancreatitis.recall.1', 'acute-pancreatitis', 1, 'recall', '{"prompt":"Sudden epigastric pain radiating to the back after a weekend of heavy drinking. Most likely diagnosis?","source_fields":["name"],"accepted_answers":[{"answer":"Acute pancreatitis","synonyms":["pancreatitis","alcoholic pancreatitis"]}],"kind":"single"}'::jsonb),
  ('acute-pancreatitis.second-order.1', 'acute-pancreatitis', 1, 'second_order', '{"prompt":"Gallstones and alcohol are the top two causes. Name three more.","source_fields":["epidemiology.risk_factors"],"accepted_answers":[{"answer":"hypertriglyceridemia","synonyms":["high triglycerides","triglycerides"]},{"answer":"post-ERCP","synonyms":["ERCP","after ERCP"]},{"answer":"medications","synonyms":["drugs","drug-induced","azathioprine","valproate","thiazides","didanosine"]},{"answer":"hypercalcemia","synonyms":["high calcium"]}],"kind":"list","required_count":3}'::jsonb),
  ('acute-pancreatitis.differentiate.1', 'acute-pancreatitis', 1, 'differentiate', '{"prompt":"Which lab finding suggests the pancreatitis is from gallstones rather than alcohol?","source_fields":["pearls[0]"],"accepted_answers":[{"answer":"ALT","synonyms":["raised ALT","high ALT","alanine aminotransferase","elevated ALT","transaminases"]}],"kind":"single"}'::jsonb),
  ('acute-pancreatitis.workup.1', 'acute-pancreatitis', 1, 'workup', '{"prompt":"Which imaging test do you order first?","source_fields":["diagnosis.confirmatory_tests"],"accepted_answers":[{"answer":"right upper quadrant ultrasound","synonyms":["RUQ ultrasound","abdominal ultrasound","ultrasound"]}],"kind":"single"}'::jsonb),
  ('acute-pancreatitis.management.1', 'acute-pancreatitis', 1, 'management', '{"prompt":"Mild pancreatitis, pain improving on day 1. When do you let them eat?","source_fields":["management.first_line"],"accepted_answers":[{"answer":"early oral feeding as tolerated","synonyms":["as tolerated","early oral feeding","when hungry","early feeding"]}],"kind":"single"}'::jsonb),
  ('acute-pancreatitis.pearl.1', 'acute-pancreatitis', 1, 'pearl', '{"prompt":"Mild gallstone pancreatitis is settling. When should the gallbladder come out?","source_fields":["management.next_line[0]"],"accepted_answers":[{"answer":"during the same admission","synonyms":["same admission","before discharge","this admission","index admission","same hospitalization"]}],"kind":"single"}'::jsonb),
  ('atrial-fibrillation.recall.1', 'atrial-fibrillation', 1, 'recall', '{"prompt":"A 70-year-old with hypertension has two days of palpitations and an irregularly irregular pulse of 130. Most likely rhythm?","source_fields":["name"],"accepted_answers":[{"answer":"Atrial fibrillation","synonyms":["AF","AFib","a fib","afib with RVR","AF with RVR"]}],"kind":"single"}'::jsonb),
  ('atrial-fibrillation.second-order.1', 'atrial-fibrillation', 1, 'second_order', '{"prompt":"Name three risk factors for atrial fibrillation.","source_fields":["epidemiology.risk_factors"],"accepted_answers":[{"answer":"older age","synonyms":["age","elderly","aging"]},{"answer":"hypertension","synonyms":["high blood pressure","HTN"]},{"answer":"heart failure","synonyms":["CHF","HF"]},{"answer":"valvular heart disease","synonyms":["valve disease","mitral stenosis","mitral regurgitation","mitral valve disease"]},{"answer":"obesity","synonyms":["obese"]},{"answer":"obstructive sleep apnea","synonyms":["OSA","sleep apnea"]},{"answer":"alcohol","synonyms":["binge drinking","holiday heart","ethanol"]},{"answer":"hyperthyroidism","synonyms":["thyrotoxicosis","Graves disease","overactive thyroid"]}],"kind":"list","required_count":3}'::jsonb),
